SELECT m.id, m.from_user_id, bu_from.username AS from_username, bu_from.avatar AS from_avatar, m.to_user_id, bu_to.username AS to_username, bu_to.avatar AS to_avatar, m.content, m.message_type, m.status, m.create_time FROM chat_message m LEFT JOIN base_user bu_from ON m.from_user_id = bu_from.id LEFT JOIN base_user bu_to ON m.to_user_id = bu_to.id
AND bu_from.username LIKE CONCAT('%', #{dto.fromUsername}, '%')
